div.script:
(function(){
var $=function(i){return document.getElementById(i)};
var EYE='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>';
var EYEOFF='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M3 3l18 18M10.6 5.1A10 10 0 0 1 12 5c6 0 10 7 10 7a17 17 0 0 1-3.2 4M6.6 6.6A17 17 0 0 0 2 12s4 7 10 7a9.7 9.7 0 0 0 4.4-1"/></svg>';
var TBL='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="1"/><path d="M3 10h18M9 4v16"/></svg>';
var NAV=[
['Import','M12 3v12M7 10l5 5 5-5M5 21h14'],
['Export','M12 15V3M7 8l5-5 5 5M5 21h14'],
['Share','M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM18 22a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM8.6 13.5l6.8 4M15.4 6.5l-6.8 4'],
['Versions','M3 12a9 9 0 1 0 3-6.7M3 4v5h5M12 7v5l3 2'],
['AI','M12 3l2 5 5 2-5 2-2 5-2-5-5-2 5-2zM19 15l.7 2 2 .7-2 .7-.7 2-.7-2-2-.7 2-.7z'],
['DBML','M8 6l-6 6 6 6M16 6l6 6-6 6'],
['Compare','M4 4h7v16H4zM13 4h7v16h-7zM6.5 9h2M6.5 13h2M15.5 9h2M15.5 13h2'],
['Tables','M3 4h18v16H3zM3 10h18M9 4v16'],
['Refs','M5 4h4v4H5zM15 16h4v4h-4zM9 6h3a3 3 0 0 1 3 3v7'],
['Diagram','M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z'],
['__sp'],
['Sign Out','M9 21H5V3h4M16 17l5-5-5-5M21 12H9']
];
var active='Diagram',h='';
NAV.forEach(function(n){
 if(n[0]==='__sp'){h+='<div style="flex:1"></div>';return}
 h+='<div class="si'+(n[0]===active?' act':'')+'" data-n="'+n[0]+'"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="'+n[1]+'"/></svg>'+n[0]+'</div>';});
$('nav').innerHTML=h;

var T=[
{n:'users',c:[['id','int','PK,AUTO'],['name','varchar(100)',''],['email','varchar(100)','']]},
{n:'todos',c:[['id','int','PK,AUTO'],['user_id','int','FK:users.id'],['category_id','int','FK:categories.id'],['title','varchar(200)',''],['completed','boolean','']]},
{n:'categories',c:[['id','int','PK,AUTO'],['name','varchar(100)','']]},
{n:'comments',c:[['id','int','PK,AUTO'],['todo_id','int','FK:todos.id'],['user_id','int','FK:users.id'],['body','text','']]},
{n:'tags',c:[['id','int','PK,AUTO'],['name','varchar(50)','']]}
];
var visible={},closed={},allClosed=false;
T.forEach(function(t){visible[t.n]=true;closed[t.n]=false});
function rels(t){var r=[];T.forEach(function(s){s.c.forEach(function(c){var m=/^FK:(\w+)\.(\w+)/.exec(c[2]);if(!m)return;
 if(s.n===t||m[1]===t)r.push({from:s.n,fc:c[0],to:m[1],tc:m[2]});});});return r;}
function other(r,t){return r.from===t?r.to:r.from}
function toast(m){var t=$('toast');t.textContent=m;t.classList.add('show');clearTimeout(toast.x);toast.x=setTimeout(function(){t.classList.remove('show')},1600)}
function keyHtml(k){if(!k)return'';return k.split(',').map(function(x){
 if(x==='PK')return'<span class="tag pk">PK</span>';
 if(x==='AUTO')return'<span class="tag au">AUTO</span>';
 if(x==='NN')return'<span class="tag nn">NOT NULL</span>';
 return'<span class="tag fk">FK ('+/^FK:(.*)/.exec(x)[1]+')</span>';}).join('')}
function build(){
 var h='';
 T.forEach(function(t,i){var r=rels(t.n);
  h+='<div class="card" id="c_'+t.n+'" data-t="'+t.n+'" style="animation-delay:'+(200+i*120)+'ms">'+
  '<div class="th"><span class="ar">▾</span><b>'+t.n+'</b><span>'+t.c.length+' columns</span>'+(r.length?'<span class="pill">'+r.length+' connections</span>':'')+'</div>'+
  '<div class="body"><table><tr><th>COLUMN</th><th>TYPE</th><th>KEY</th></tr>'+
  t.c.map(function(c){return'<tr><td><span>'+c[0]+'</span></td><td>'+c[1]+'</td><td>'+keyHtml(c[2])+'</td></tr>'}).join('')+'</table>'+
  (r.length?'<div class="rt">RELATIONSHIPS / CONNECTIONS</div>'+r.map(function(x){var o=other(x,t.n);
   return'<div class="rl"><i>↗</i><span style="color:#0891b2">'+x.from+'.'+x.fc+'</span>→<span>'+x.to+'.'+x.tc+'</span><span class="chip" data-go="'+o+'">👁 View '+o+'</span></div>'}).join(''):'')+
  '</div></div>';});
 $('list').innerHTML=h+'<div class="empty" id="empty" style="display:none">No tables selected. Open the panel to show tables.</div>';
}
function setVis(n,v,instant){
 visible[n]=v;var e=$('c_'+n);if(!e)return;
 clearTimeout(e._t);
 if(v){e.style.display='';e.style.animation='none';void e.offsetWidth;e.style.animation='';e.classList.remove('gone');}
 else{e.classList.add('gone');e._t=setTimeout(function(){e.style.display='none'},instant?0:300);}
}
function render(){
 var f=($('q').value||'').toLowerCase().trim(),p='';
 T.forEach(function(t){if(f&&t.n.indexOf(f)<0)return;var n=rels(t.n).length;
  p+='<div class="row'+(visible[t.n]?'':' off')+'" data-p="'+t.n+'"><span>'+TBL+t.n+(n?'<small>('+n+' rel)</small>':'')+'</span><span class="eye">'+(visible[t.n]?EYE:EYEOFF)+'</span></div>'});
 $('plist').innerHTML=p;
 var c=T.filter(function(t){return visible[t.n]}).length;
 $('sel').textContent=c+'/'+T.length+' tables selected';
 $('empty').style.display=c?'none':'';
}
function hover(name,on){var rr=on?rels(name).map(function(r){return other(r,name)}):[];
 T.forEach(function(t){var e=$('c_'+t.n);if(!e)return;
  e.classList.toggle('hl',on&&t.n===name);e.classList.toggle('rel',on&&rr.indexOf(t.n)>-1);
  e.classList.toggle('dim',on&&t.n!==name&&rr.indexOf(t.n)<0);});}
function go(n){if(!visible[n])setVis(n,true);closed[n]=false;$('c_'+n).classList.remove('closed');render();var e=$('c_'+n);
 e.classList.remove('flash');void e.offsetWidth;e.classList.add('flash');setTimeout(function(){e.classList.remove('flash')},1000);}
function togglePanel(f){var o=typeof f==='boolean'?f:!$('panel').classList.contains('open');
 $('panel').classList.toggle('open',o);$('pbtn').classList.toggle('on',o);}
function download(){
 var md='# Data Dictionary\n\n';
 T.filter(function(t){return visible[t.n]}).forEach(function(t){
  md+='## '+t.n+'\n\n| Column | Type | Key |\n|---|---|---|\n';
  t.c.forEach(function(c){md+='| '+c[0]+' | '+c[1]+' | '+c[2].replace(/FK:/,'FK → ').replace(/,/g,', ')+' |\n'});
  var r=rels(t.n);if(r.length){md+='\n**Relationships**\n\n';r.forEach(function(x){md+='- `'+x.from+'.'+x.fc+'` → `'+x.to+'.'+x.tc+'`\n'});}
  md+='\n';});
 var b=new Blob([md],{type:'text/markdown'}),a=document.createElement('a');
 a.href=URL.createObjectURL(b);a.download='data-dictionary.md';document.body.appendChild(a);a.click();a.remove();
 var d=$('dl');$('dlt').textContent='✓ Downloaded';d.classList.add('done');
 setTimeout(function(){$('dlt').textContent='Download Markdown';d.classList.remove('done')},1500);}

$('nav').addEventListener('click',function(e){var s=e.target.closest('.si');if(!s)return;var n=s.getAttribute('data-n');
 if(n==='Export'){download();return}
 if(n==='Tables'){togglePanel();return}
 if(n==='Sign Out'||n==='Import'||n==='Share'||n==='Versions'||n==='AI'||n==='DBML'||n==='Compare'||n==='Refs'){toast(n+' (demo only)');return}
 active=n;[].forEach.call(document.querySelectorAll('.si'),function(x){x.classList.toggle('act',x.getAttribute('data-n')===n)});});
var sc=false;$('sw').onclick=function(){sc=!sc;$('side').style.width=sc?'0':'72px';$('side').style.padding=sc?'0':'10px 0';$('side').style.borderRight=sc?'0':'';$('sw').style.right=sc?'-26px':'-12px';$('sw').style.background='#dbeafe';};
$('list').addEventListener('click',function(e){
 var g=e.target.closest('[data-go]');if(g){go(g.getAttribute('data-go'));return}
 var th=e.target.closest('.th');if(th){var c=th.parentNode,n=c.getAttribute('data-t');closed[n]=!closed[n];c.classList.toggle('closed',closed[n]);}});
$('list').addEventListener('mouseover',function(e){var c=e.target.closest('.card');if(c)hover(c.getAttribute('data-t'),true)});
$('list').addEventListener('mouseout',function(e){var c=e.target.closest('.card');if(c&&!c.contains(e.relatedTarget))hover(c.getAttribute('data-t'),false)});
$('plist').addEventListener('click',function(e){var r=e.target.closest('[data-p]');if(!r)return;var n=r.getAttribute('data-p');setVis(n,!visible[n]);render();hover('',false);});
$('plist').addEventListener('mouseover',function(e){var r=e.target.closest('[data-p]');if(r&&visible[r.getAttribute('data-p')])hover(r.getAttribute('data-p'),true)});
$('plist').addEventListener('mouseout',function(){hover('',false)});
$('q').addEventListener('input',render);
$('pbtn').onclick=function(){togglePanel()};
$('px').onclick=function(){togglePanel(false)};
$('allbtn').onclick=function(){var any=T.some(function(t){return visible[t.n]});T.forEach(function(t,i){setTimeout(function(){setVis(t.n,!any);render()},i*90)});};
$('toggleAll').onclick=function(){allClosed=!allClosed;T.forEach(function(t){closed[t.n]=allClosed});
 $('toggleAll').textContent=allClosed?'⌄ Expand All':'⌃ Collapse All';
 T.forEach(function(t){var e=$('c_'+t.n);if(e)e.classList.toggle('closed',allClosed)});};
$('dl').onclick=download;

var auto={i:0,pause:0};
function listTo(n){var e=$('c_'+n);$('list').scrollTo({top:Math.max(0,e.offsetTop-24),behavior:'smooth'})}
function ping(n){var r=document.querySelector('[data-p="'+n+'"]');if(r){r.classList.add('ping');setTimeout(function(){r.classList.remove('ping')},900)}}
function showT(n){setVis(n,true);render();ping(n);setTimeout(function(){listTo(n)},350)}
function hideT(n){ping(n);setTimeout(function(){setVis(n,false);render()},350)}
function resetDemo(){hover('',false);allClosed=false;$('toggleAll').textContent='\u2303 Collapse All';
 T.forEach(function(t){closed[t.n]=false;var e=$('c_'+t.n);if(e)e.classList.remove('closed')});
 ['categories','comments','tags'].forEach(function(n){if(visible[n])setVis(n,false)});
 ['users','todos'].forEach(function(n){if(!visible[n])setVis(n,true)});
 render();$('list').scrollTo({top:0,behavior:'smooth'});togglePanel(true)}
var steps=[
 resetDemo,
 function(){hover('users',true)},
 function(){hover('users',false);hover('todos',true)},
 function(){hover('todos',false);showT('categories')},
 function(){hover('categories',true)},
 function(){hover('categories',false);showT('comments')},
 function(){hover('comments',true)},
 function(){hover('comments',false);showT('tags')},
 function(){$('toggleAll').onclick()},
 function(){$('toggleAll').onclick()},
 function(){var d=$('dl');d.classList.add('pulse');setTimeout(function(){d.classList.remove('pulse')},700)},
 function(){hideT('tags')},
 function(){hideT('comments')},
 function(){hideT('categories')}
];
function tick(){
 if(Date.now()<auto.pause){setTimeout(tick,700);return}
 steps[auto.i%steps.length]();auto.i++;setTimeout(tick,1700);}
$('app').addEventListener('pointerdown',function(){auto.pause=Date.now()+6000});
setTimeout(tick,3200);
build();['categories','comments','tags'].forEach(function(n){setVis(n,false,true)});render();setTimeout(function(){togglePanel(true)},1100);
})();
